"""Pure case catalog validation and independent expected-result scoring."""
from __future__ import annotations
import json
import math
import re
from pathlib import Path
from typing import Any, Iterable
from embodied_agent.paths import PROJECT_ROOT as ROOT
from embodied_agent.execution.home_contracts import HomeExecutionError, validate_home_plan

def _read_json(path: Path) -> dict[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError(f"Expected a JSON object: {path}")
    return value

def _contains(actual: Any, expected: Any, path: str = "map_snapshot") -> list[str]:
    if isinstance(expected, dict):
        if not isinstance(actual, dict):
            return [f"{path}: expected an object"]
        return [failure for key, value in expected.items()
                for failure in _contains(actual.get(key), value, f"{path}.{key}")]
    if isinstance(expected, list):
        if not isinstance(actual, list) or len(actual) != len(expected):
            return [f"{path}: expected {expected!r}, got {actual!r}"]
        return [failure for index, value in enumerate(expected)
                for failure in _contains(actual[index], value, f"{path}[{index}]")]
    equal = math.isclose(actual, expected, rel_tol=1e-8, abs_tol=1e-8) if (
        isinstance(actual, (int, float)) and isinstance(expected, (int, float))
    ) else actual == expected
    return [] if equal else [f"{path}: expected {expected!r}, got {actual!r}"]


def check_expected(result: dict[str, Any], expected: dict[str, Any]) -> tuple[bool, list[str]]:
    failures: list[str] = []
    for key, value in {"status": "SUCCESS", **expected}.items():
        if key == "map_contains":
            failures.extend(_contains(result.get("map_snapshot"), value))
        elif result.get(key) != value:
            failures.append(f"{key}: expected {value!r}, got {result.get(key)!r}")
    return not failures, failures


def validate_case(case: dict[str, Any], agents: set[str]) -> None:
    if not isinstance(case, dict) or not isinstance(case.get("case_id"), str) or not case["case_id"].strip():
        raise ValueError("Each case requires a nonempty case_id")
    if "map_id" in case and (not isinstance(case["map_id"], str) or not re.fullmatch(r"[a-z][a-z0-9_-]*", case["map_id"])):
        raise ValueError(f"Invalid map_id in {case['case_id']}")
    if "initial_overrides" in case:
        overrides = case["initial_overrides"]
        if not isinstance(overrides, dict) or set(overrides) - {"cube_position_m", "danger_zone", "targets"}:
            raise ValueError("initial_overrides only supports cube_position_m, danger_zone and targets")
    if "steps" in case and any(key in case for key in ("instruction", "agent", "expected", "robot_plan", "test_fault_protocol")):
        raise ValueError("A case must use steps or a single instruction, not both")
    steps = case.get("steps", [case])
    if not isinstance(steps, list) or not steps:
        raise ValueError("Case steps must be a nonempty list")
    for step in steps:
        if not isinstance(step, dict) or not isinstance(step.get("instruction"), str) or not step["instruction"].strip():
            raise ValueError("Each step requires a nonempty instruction")
        if step.get("agent", "robot") not in agents:
            raise ValueError(f"Unknown case agent: {step.get('agent')}")
        expected = step.get("expected", {"status": "SUCCESS"})
        if not isinstance(expected, dict) or not expected or set(expected) - {"status", "error_code", "target_id", "map_contains", "transport_success"}:
            raise ValueError("Invalid expected assertion; supported keys: status, error_code, target_id, map_contains, transport_success")
        if expected.get("status", "SUCCESS") not in {"SUCCESS", "FAILED", "ABORTED"}:
            raise ValueError("Invalid expected status")
        for key in ("error_code", "target_id"):
            if key in expected and expected[key] is not None and not isinstance(expected[key], str):
                raise ValueError(f"expected.{key} must be a string or null")
        if "map_contains" in expected and (not isinstance(expected["map_contains"], dict) or not expected["map_contains"]):
            raise ValueError("expected.map_contains must be a nonempty object")
        if "transport_success" in expected and type(expected["transport_success"]) is not bool:
            raise ValueError("expected.transport_success must be a boolean")
        if "robot_plan" in step:
            if step.get("agent", "robot") not in {"robot"}:
                raise ValueError("robot_plan requires the existing robot agent")
            try:
                validate_home_plan(step["robot_plan"])
            except HomeExecutionError as exc:
                raise ValueError(f"Invalid trusted robot_plan: {exc.code}: {exc}") from exc
        if "test_fault_protocol" in step:
            if step["test_fault_protocol"] != "navigation_waypoint_into_tea_table_v1":
                raise ValueError("Unknown trusted test_fault_protocol")
            if "robot_plan" not in step or step["robot_plan"] != {"schema_version": 1, "actions": [{"skill": "navigate", "target": "tea_table"}]}:
                raise ValueError("Navigation fault requires the fixed tea_table navigation fixture")


def load_cases(path: Path | None = None, *, root: Path = ROOT,
               known_agents: Iterable[str] = ("robot", "environment")) -> list[dict[str, Any]]:
    root = Path(root)
    source = Path(path or root / "configs" / "demo_cases.json").resolve()
    payload = _read_json(source)
    if type(payload.get("schema_version")) is not int or payload.get("schema_version") != 1 or not isinstance(payload.get("cases"), list):
        raise ValueError("Case file requires schema_version=1 and a cases array")
    if "include_m3_cases" in payload and type(payload["include_m3_cases"]) is not bool:
        raise ValueError("include_m3_cases must be a boolean")
    cases: list[dict[str, Any]] = []
    scenes = {s["scenario_id"]: s for s in _read_json(root / "configs" / "m2_scenarios.json")["scenarios"]}

    def convert_legacy(case: dict[str, Any]) -> dict[str, Any]:
        if "scenario_id" not in case:
            return case
        if case.get("scenario_id") not in scenes:
            raise ValueError(f"Unknown legacy scenario_id: {case.get('scenario_id')}")
        scene = scenes[case["scenario_id"]]
        if case.get("seed") != scene["seed"] or case.get("expected_target_id") != f"target_{scene['target']}":
            raise ValueError(f"Legacy case seed/target mismatch: {case.get('case_id')}")
        return {"case_id": case["case_id"], "name": case["case_id"], "map_id": "classic",
                "agent": "robot", "instruction": case["instruction"],
                "initial_overrides": {"cube_position_m": scene["cube_position_m"]},
                "expected": {"status": "SUCCESS", "target_id": case["expected_target_id"]},
                "legacy_scenario_id": scene["scenario_id"], "legacy_seed": scene["seed"]}

    if payload.get("include_m3_cases", False):
        legacy = _read_json(root / "configs" / "m3_cases.json")
        for case in legacy["cases"]:
            cases.append(convert_legacy(case))
    cases.extend(convert_legacy(case) for case in payload["cases"])
    identifiers: set[str] = set()
    agents = set(known_agents)
    for case in cases:
        validate_case(case, agents)
        if case["case_id"] in identifiers:
            raise ValueError(f"Duplicate case_id: {case['case_id']}")
        identifiers.add(case["case_id"])
    if not cases:
        raise ValueError("Case file contains no cases")
    return cases

src/embodied_agent/evaluation/evidence.p:
"""Append-only run evidence and shared JSON serialization."""

from __future__ import annotations

import csv
import datetime as dt
import hashlib
import json
from dataclasses import asdict
from pathlib import Path
from typing import Any

import numpy as np

from ..contracts import Observation

def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def jsonable(value: Any) -> Any:
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, (np.floating, np.integer)):
        return value.item()
    if hasattr(value, "to_dict"):
        return value.to_dict()
    if hasattr(value, "__dataclass_fields__"):
        return asdict(value)
    if isinstance(value, dict):
        return {str(key): jsonable(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [jsonable(item) for item in value]
    return value




class LegacyRunWriter:
    """Append-only event, episode, and trajectory evidence for one run."""

    TRAJECTORY_FIELDS = (
        "run_id",
        "episode_id",
        "phase",
        "step",
        "sim_time_s",
        "ee_target_xyz_m",
        "ee_actual_xyz_m",
        "ee_position_error_m",
        "cube_xyz_m",
        "cube_linear_speed_m_s",
        "cube_angular_speed_rad_s",
        "gripper_ctrl",
        "finger_qpos_m",
        "contacts",
        "minimum_contact_distance_so_far_m",
        "minimum_danger_zone_separation_so_far_m",
        "danger_zone_clear",
        "warnings",
        "finite_state",
    )

    def __init__(self, output_dir: Path, run_id: str):
        self.output_dir = output_dir
        self.run_id = run_id
        self._event_sequence = 0
        self._trajectory_new = not (output_dir / "trajectory.csv").exists()

    def emit(
        self,
        episode_id: str,
        event: str,
        state: str,
        detail: dict[str, Any] | None = None,
        observation: Observation | None = None,
    ) -> None:
        self._event_sequence += 1
        row: dict[str, Any] = {
            "run_id": self.run_id,
            "episode_id": episode_id,
            "sequence": self._event_sequence,
            "timestamp_utc": dt.datetime.now(dt.timezone.utc).isoformat(),
            "event": event,
            "state": state,
            "remaining_observation_id": observation.obs_id if observation else None,
        }
        if observation is not None:
            row["observation"] = observation.to_dict()
        if detail:
            row["detail"] = detail
        path = self.output_dir / "events.jsonl"
        with path.open("a", encoding="utf-8", newline="\n") as stream:
            stream.write(json.dumps(jsonable(row), ensure_ascii=False, separators=(",", ":")) + "\n")

    def append_episode(self, result: dict[str, Any]) -> None:
        path = self.output_dir / "episodes.jsonl"
        with path.open("a", encoding="utf-8", newline="\n") as stream:
            stream.write(json.dumps(jsonable(result), ensure_ascii=False, separators=(",", ":")) + "\n")

    def append_trajectory(self, episode_id: str, samples: list[dict[str, Any]]) -> None:
        path = self.output_dir / "trajectory.csv"
        with path.open("a", encoding="utf-8", newline="") as stream:
            writer = csv.DictWriter(stream, fieldnames=self.TRAJECTORY_FIELDS)
            if self._trajectory_new:
                writer.writeheader()
                self._trajectory_new = False
            for sample in samples:
                row = {"run_id": self.run_id, "episode_id": episode_id, **sample}
                writer.writerow(
                    {
                        key: json.dumps(value, ensure_ascii=False, separators=(",", ":"))
                        if isinstance(value, (list, dict))
                        else value
                        for key, value in row.items()
                    }
                )

    def finish(self, results: list[dict[str, Any]], manifest: dict[str, Any]) -> dict[str, Any]:
        statuses = {name: sum(row["status"] == name for row in results) for name in ("SUCCESS", "FAILED", "ABORTED")}
        summary = {
            **manifest,
            "run_id": self.run_id,
            "date_utc": dt.datetime.now(dt.timezone.utc).isoformat(),
            "episode_count": len(results),
            "success_count": statuses["SUCCESS"],
            "failure_count": statuses["FAILED"],
            "aborted_count": statuses["ABORTED"],
            "not_run_count": sum(row["status"] == "NOT_RUN" for row in results),
            "all_pass": bool(results) and statuses["SUCCESS"] == len(results),
            "episodes": [
                {
                    "episode_id": row["episode_id"],
                    "case_id": row.get("case_id"),
                    "status": row["status"],
                    "error_code": row.get("error_code"),
                    "target_id": row.get("target_id"),
                    "expected_target_id": row.get("expected_target_id"),
                    "step_count": row.get("step_count", 0),
                    "planner_kind": row.get("planner_kind"),
                    "llm_request_count": row.get("llm_request_count", 0),
                    "token_usage": row.get("token_usage"),
                    "wall_time_s": row.get("wall_time_s"),
                    "postconditions": row.get("postconditions"),
                }
                for row in results
            ],
        }
        (self.output_dir / "summary.json").write_text(
            json.dumps(jsonable(summary), ensure_ascii=False, indent=2) + "\n", encoding="utf-8"
        )
        return summary

src/embodied_agent/evaluation/task_recor:
"""Versioned, atomic task JSON records; prediction and execution stay separate.

A record is owned by one active executor. Independent executors may share a store:
the SQLite counter serializes only filename allocation, not robot execution. Once
finished, a task is immutable. A later repair belongs to a new attempt while the
task is running, or to a new task after it has been finished.
"""

from __future__ import annotations

import copy
import datetime as dt
import hashlib
import json
import os
import re
import sqlite3
import tempfile
import threading
import uuid
from contextlib import closing
from dataclasses import asdict, is_dataclass
from pathlib import Path
from typing import Any, Callable


SCHEMA_VERSION = 1
SHANGHAI = dt.timezone(dt.timedelta(hours=8), name="Asia/Shanghai")
MAP_ALIASES = {"classic": "cls", "alternate": "alt", "home_living_room": "hlr"}
_NAME = re.compile(r"^(\d{8})_([a-z0-9_-]+)_(\d{6,})\.json$")
_TERMINAL = frozenset({"COMPLETED", "FAILED", "ABORTED"})


class TaskRecordError(ValueError):
    """Malformed record or an invalid lifecycle transition."""


def _now() -> dt.datetime:
    return dt.datetime.now(dt.timezone.utc)


def _timestamp(value: dt.datetime) -> str:
    if value.tzinfo is None:
        raise TaskRecordError("task-record clock must return a timezone-aware datetime")
    return value.astimezone(SHANGHAI).isoformat(timespec="microseconds")


def map_alias(map_id: str) -> str:
    """Keep familiar map names short and unknown names readable and distinct."""
    if map_id in MAP_ALIASES:
        return MAP_ALIASES[map_id]
    readable = re.sub(r"[^a-z0-9]+", "-", map_id.lower()).strip("-")[:16] or "map"
    return f"{readable}-{hashlib.sha256(map_id.encode('utf-8')).hexdigest()[:12]}"


def _json_value(value: Any) -> Any:
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        if any(not isinstance(key, str) for key in value):
            raise TaskRecordError("task-record JSON object keys must be strings")
        return {key: _json_value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_value(item) for item in value]
    if isinstance(value, Path):
        return str(value)
    if hasattr(value, "to_dict"):
        return _json_value(value.to_dict())
    if is_dataclass(value) and not isinstance(value, type):
        return _json_value(asdict(value))
    # NumPy arrays and scalars are supported without importing NumPy here.
    if hasattr(value, "tolist"):
        return _json_value(value.tolist())
    if hasattr(value, "item"):
        return _json_value(value.item())
    raise TaskRecordError(f"unsupported task-record JSON value: {type(value).__name__}")


def _encode(value: Any) -> str:
    try:
        return json.dumps(_json_value(value), ensure_ascii=False, indent=2, allow_nan=False) + "\n"
    except (TypeError, ValueError) as exc:
        raise TaskRecordError(f"invalid task-record JSON: {exc}") from exc


def _clone(value: Any) -> Any:
    """Detach caller-owned objects and normalize them into strict JSON values."""
    return json.loads(_encode(copy.deepcopy(value)))


def _definition_digest(definition: Any) -> str:
    """Identify the exact JSON map definition, independent of key ordering."""
    try:
        canonical = json.dumps(definition, ensure_ascii=False, sort_keys=True,
                               separators=(",", ":"), allow_nan=False)
    except (TypeError, ValueError) as exc:
        raise TaskRecordError(f"invalid map definition JSON: {exc}") from exc
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def _atomic_write(path: Path, value: dict[str, Any]) -> None:
    text = _encode(value)  # Reject invalid input before touching any file.
    descriptor, temporary = tempfile.mkstemp(prefix=f".{path.stem}-", suffix=".tmp", dir=path.parent)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8", newline="\n") as stream:
            stream.write(text)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass


def _reject_constant(value: str) -> None:
    raise TaskRecordError(f"non-finite JSON number: {value}")


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise TaskRecordError(f"duplicate JSON key: {key}")
        result[key] = value
    return result


def _validate_record(data: Any) -> dict[str, Any]:
    if (not isinstance(data, dict) or type(data.get("schema_version")) is not int
            or data["schema_version"] != SCHEMA_VERSION):
        raise TaskRecordError("unsupported or missing task-record schema_version")
    required = {"task_id", "date", "sequence", "map", "initial_state", "natural_language",
                "versions", "metadata", "attempts", "final_state", "outcome", "costs",
                "record_status", "created_at", "updated_at", "finished_at"}
    missing = required - data.keys()
    if missing:
        raise TaskRecordError(f"task record is missing fields: {sorted(missing)}")
    if (not isinstance(data["record_status"], str)
            or data["record_status"] not in _TERMINAL | {"RUNNING"}):
        raise TaskRecordError("invalid record_status")
    if (not isinstance(data["map"], dict)
            or not {"id", "alias", "definition", "definition_sha256"} <= data["map"].keys()):
        raise TaskRecordError("invalid map definition")
    if not isinstance(data["map"]["id"], str) or not data["map"]["id"].strip():
        raise TaskRecordError("invalid map id")
    if data["map"]["alias"] != map_alias(data["map"]["id"]):
        raise TaskRecordError("map alias does not match map id")
    if data["map"]["definition_sha256"] != _definition_digest(data["map"]["definition"]):
        raise TaskRecordError("map definition_sha256 does not match its definition")
    if (not isinstance(data["date"], str) or not re.fullmatch(r"\d{8}", data["date"])
            or type(data["sequence"]) is not int or data["sequence"] < 1):
        raise TaskRecordError("invalid date or sequence")
    if not isinstance(data["task_id"], str) or not re.fullmatch(r"[0-9a-f]{32}", data["task_id"]):
        raise TaskRecordError("task_id must be an independent UUID hex string")
    if not isinstance(data["natural_language"], str):
        raise TaskRecordError("natural_language must be a string")
    for field in ("versions", "metadata", "costs"):
        if not isinstance(data[field], dict):
            raise TaskRecordError(f"{field} must be an object")
    if data["outcome"] is not None and not isinstance(data["outcome"], dict):
        raise TaskRecordError("outcome must be null or an object")
    for field in ("created_at", "updated_at", "finished_at"):
        if field == "finished_at" and data[field] is None:
            continue
        if not isinstance(data[field], str):
            raise TaskRecordError(f"{field} must be an ISO datetime")
        try:
            timestamp = dt.datetime.fromisoformat(data[field])
        except ValueError as exc:
            raise TaskRecordError(f"{field} must be an ISO datetime") from exc
        if timestamp.utcoffset() != dt.timedelta(hours=8):
            raise TaskRecordError(f"{field} must use UTC+08:00")
        if field == "created_at" and timestamp.strftime("%Y%m%d") != data["date"]:
            raise TaskRecordError("date must be the Shanghai task-start date")
    if not isinstance(data["attempts"], list):
        raise TaskRecordError("attempts must be an array")
    for index, attempt in enumerate(data["attempts"], 1):
        if (not isinstance(attempt, dict) or type(attempt.get("attempt_id")) is not int
                or attempt["attempt_id"] != index):
            raise TaskRecordError("attempt ids must be continuous and start at 1")
        attempt_fields = {"parent_attempt_id", "trigger_event_id", "phase", "started_at", "updated_at",
                          "planning_observation", "model_input", "plan", "proposal", "actual_execution", "metadata",
                          "events", "checks", "tool_events", "feedback"}
        if attempt_fields - attempt.keys():
            raise TaskRecordError(f"attempt {index}: missing fields {sorted(attempt_fields - attempt.keys())}")
        parent = attempt["parent_attempt_id"]
        if parent is not None and (type(parent) is not int or not 1 <= parent < index):
            raise TaskRecordError(f"attempt {index}: parent must precede the child")
        if not isinstance(attempt["phase"], str) or not isinstance(attempt["metadata"], dict):
            raise TaskRecordError(f"attempt {index}: invalid phase or metadata")
        for collection in ("events", "checks", "tool_events"):
            if not isinstance(attempt.get(collection), list):
                raise TaskRecordError(f"attempt {index}: {collection} must be an array")
            for sequence, event in enumerate(attempt[collection], 1):
                if (not isinstance(event, dict) or event.get("event_id") != f"{index}:{collection}:{sequence}"
                        or type(event.get("sequence")) is not int or event["sequence"] != sequence):
                    raise TaskRecordError(f"attempt {index}: invalid {collection} event identity")
        if not isinstance(attempt.get("feedback"), dict):
            raise TaskRecordError(f"attempt {index}: feedback must be an object")
        if (not {"return_to_caller", "sent_to_agent"} <= attempt["feedback"].keys()
                or not isinstance(attempt["feedback"]["sent_to_agent"], list)):
            raise TaskRecordError(f"attempt {index}: invalid feedback destinations")
    if data["record_status"] in _TERMINAL:
        if data["finished_at"] is None or not isinstance(data["outcome"], dict):
            raise TaskRecordError("finished records require finished_at and outcome")
        if not isinstance(data["outcome"].get("status"), str):
            raise TaskRecordError("finished records require an outcome status")
    elif data["finished_at"] is not None or data["outcome"] is not None:
        raise TaskRecordError("running records cannot contain a final outcome")
    _encode(data)
    return data


class TaskRecordStore:
    """A directory of self-contained tasks and a persistent daily counter.

    The sequence is global within this directory, across maps and processes.
    Gaps after crashes are intentional. ``query`` skips malformed records and
    exposes their paths and reasons through ``errors``. Training queries require
    explicit successful verification; a SUCCESS string alone is insufficient.
    Returned tasks retain failed attempts. Training consumers must label those
    separately rather than treating every attempt in a successful task as a
    positive demonstration.
    """

    def __init__(self, root: str | Path, *, clock: Callable[[], dt.datetime] | None = None):
        self.root = Path(root).resolve()
        self.root.mkdir(parents=True, exist_ok=True)
        self._clock = clock or _now
        self.errors: list[dict[str, str]] = []

    def _allocate(self, date: str, alias: str) -> tuple[Path, int]:
        with closing(sqlite3.connect(self.root / ".task-sequences.sqlite3", timeout=30)) as connection:
            connection.execute("CREATE TABLE IF NOT EXISTS daily (date TEXT PRIMARY KEY, sequence INTEGER NOT NULL)")
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute("SELECT sequence FROM daily WHERE date = ?", (date,)).fetchone()
            # Recover numbering if records predate the counter or it was rebuilt.
            disk_max = max((int(match.group(3)) for path in self.root.glob(f"{date}_*.json")
                            if (match := _NAME.fullmatch(path.name))), default=0)
            sequence = max(int(row[0]) if row else 0, disk_max) + 1
            connection.execute("INSERT INTO daily(date, sequence) VALUES (?, ?) "
                               "ON CONFLICT(date) DO UPDATE SET sequence=excluded.sequence", (date, sequence))
            connection.commit()
        path = self.root / f"{date}_{alias}_{sequence:06d}.json"
        # Never replace a pre-existing task, even if another writer bypassed the
        # counter. The empty exclusive reservation is replaced atomically below.
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        os.close(descriptor)
        return path, sequence

    def begin(self, *, map_id: str, map_definition: Any, initial_state: Any,
              natural_language: str, versions: dict[str, Any] | None = None,
              metadata: dict[str, Any] | None = None) -> "TaskRecord":
        if not isinstance(map_id, str) or not map_id.strip():
            raise TaskRecordError("map_id must be a nonempty string")
        if not isinstance(natural_language, str):
            raise TaskRecordError("natural_language must be a string")
        timestamp = _timestamp(self._clock())
        date = timestamp[:10].replace("-", "")
        alias = map_alias(map_id)
        data = _clone({"schema_version": SCHEMA_VERSION, "task_id": None, "date": date,
                       "sequence": None, "map": {"id": map_id, "alias": alias, "definition": map_definition},
                       "initial_state": initial_state, "natural_language": natural_language,
                       "versions": versions or {}, "metadata": metadata or {}, "attempts": [],
                       "final_state": None, "outcome": None, "costs": {}, "record_status": "RUNNING",
                       "created_at": timestamp, "updated_at": timestamp, "finished_at": None})
        data["map"]["definition_sha256"] = _definition_digest(data["map"]["definition"])
        try:
            path, sequence = self._allocate(date, alias)
        except FileExistsError:
            # A foreign writer claimed the exact candidate: consume a new number.
            path, sequence = self._allocate(date, alias)
        data["task_id"], data["sequence"] = uuid.uuid4().hex, sequence
        try:
            _validate_record(data)
            _atomic_write(path, data)
        except BaseException:
            # Allocation gaps remain; no valid task is claimed to have begun.
            path.unlink(missing_ok=True)
            raise
        return TaskRecord(path, data, self._clock)

    def list(self) -> list[Path]:
        return sorted((path for path in self.root.glob("*.json") if _NAME.fullmatch(path.name)),
                      key=lambda path: (_NAME.fullmatch(path.name).group(1),
                                        int(_NAME.fullmatch(path.name).group(3)), path.name))

    def load(self, path_or_task_id: str | Path) -> dict[str, Any]:
        requested = str(path_or_task_id)
        if re.fullmatch(r"[0-9a-f]{32}", requested):
            for candidate in self.list():
                try:
                    data = self.load(candidate)
                except TaskRecordError:
                    continue
                if data["task_id"] == requested:
                    return data
            raise TaskRecordError(f"cannot find task_id {requested} in {self.root}")
        path = Path(path_or_task_id)
        if not path.is_absolute():
            # Accept either a task id or a filename local to the store.
            path = self.root / path
        if path.suffix != ".json":
            path = path.with_suffix(".json")
        try:
            with path.open("r", encoding="utf-8") as stream:
                data = json.load(stream, parse_constant=_reject_constant, object_pairs_hook=_unique_object)
            data = _validate_record(data)
            expected_name = f"{data['date']}_{data['map']['alias']}_{data['sequence']:06d}.json"
            if path.name != expected_name:
                raise TaskRecordError("filename does not match the task date, map alias, and sequence")
            return data
        except (OSError, ValueError) as exc:
            raise TaskRecordError(f"cannot load task record {path}: {exc}") from exc

    def query(self, *, map_id: str | None = None, status: str | None = None,
              date: str | None = None, record_status: str | None = None,
              training_only: bool = False) -> list[dict[str, Any]]:
        self.errors = []
        records = []
        for path in self.list():
            try:
                data = self.load(path)
            except TaskRecordError as exc:
                self.errors.append({"path": str(path), "error": str(exc)})
                continue
            outcome = data["outcome"] or {}
            if map_id is not None and data["map"]["id"] != map_id:
                continue
            if status is not None and outcome.get("status") != status:
                continue
            if date is not None and data["date"] != date.replace("-", ""):
                continue
            if record_status is not None and data["record_status"] != record_status:
                continue
            if training_only and not (data["record_status"] == "COMPLETED"
                                      and outcome.get("status") == "SUCCESS"
                                      and outcome.get("verified") is True):
                continue
            records.append(data)
        return records


class TaskRecord:
    """Durable updates for one running task; every public value is detached."""

    def __init__(self, path: Path, data: dict[str, Any], clock: Callable[[], dt.datetime]):
        self.path = path
        self._data = _clone(data)
        self._clock = clock
        self._lock = threading.RLock()

    @property
    def task_id(self) -> str:
        return self._data["task_id"]

    @property
    def data(self) -> dict[str, Any]:
        with self._lock:
            return copy.deepcopy(self._data)

    def _candidate(self) -> dict[str, Any]:
        if self._data["record_status"] != "RUNNING":
            raise TaskRecordError("finished task records are immutable")
        return copy.deepcopy(self._data)

    def _commit(self, candidate: dict[str, Any]) -> None:
        candidate["updated_at"] = _timestamp(self._clock())
        candidate = _clone(candidate)
        _validate_record(candidate)
        _atomic_write(self.path, candidate)
        self._data = candidate

    @staticmethod
    def _attempt(data: dict[str, Any], attempt_id: int | None) -> dict[str, Any]:
        if attempt_id is None:
            attempt_id = len(data["attempts"])
        if type(attempt_id) is not int or not 1 <= attempt_id <= len(data["attempts"]):
            raise TaskRecordError("attempt_id does not identify an existing attempt")
        return data["attempts"][attempt_id - 1]

    def append_attempt(self, *, planning_observation: Any = None, model_input: Any = None,
                       plan: Any = None, proposal: Any = None, parent_attempt_id: int | None = None,
                       trigger_event_id: str | None = None, metadata: dict[str, Any] | None = None) -> int:
        with self._lock:
            candidate = self._candidate()
            if parent_attempt_id is not None:
                self._attempt(candidate, parent_attempt_id)
            attempt_id = len(candidate["attempts"]) + 1
            timestamp = _timestamp(self._clock())
            candidate["attempts"].append({"attempt_id": attempt_id, "parent_attempt_id": parent_attempt_id,
                                         "trigger_event_id": trigger_event_id, "phase": "PLANNING",
                                         "started_at": timestamp, "updated_at": timestamp,
                                         "planning_observation": planning_observation, "model_input": model_input,
                                         "plan": plan, "proposal": proposal, "actual_execution": None,
                                         "metadata": metadata or {},
                                         "events": [], "checks": [], "tool_events": [],
                                         "feedback": {"return_to_caller": None, "sent_to_agent": []}})
            self._commit(candidate)
            return attempt_id

    def update_attempt(self, attempt_id: int | None = None, **fields: Any) -> None:
        immutable = {"planning_observation", "model_input", "plan", "proposal", "actual_execution",
                     "parent_attempt_id", "trigger_event_id"}
        allowed = immutable | {"phase", "metadata", "feedback"}
        if set(fields) - allowed:
            raise TaskRecordError(f"unsupported attempt fields: {sorted(set(fields) - allowed)}")
        with self._lock:
            candidate = self._candidate()
            attempt = self._attempt(candidate, attempt_id)
            for field, value in fields.items():
                if field in immutable and attempt[field] is not None:
                    raise TaskRecordError(f"attempt {attempt['attempt_id']} {field} is immutable; append a new attempt")
                if field == "parent_attempt_id" and value is not None:
                    self._attempt(candidate, value)
                    if value >= attempt["attempt_id"]:
                        raise TaskRecordError("parent_attempt_id must precede the child attempt")
                if field == "feedback":
                    raise TaskRecordError("use set_attempt_feedback to preserve feedback destinations")
                if field == "metadata":
                    if not isinstance(value, dict):
                        raise TaskRecordError("attempt metadata must be an object")
                    attempt[field].update(value)
                else:
                    attempt[field] = value
            attempt["updated_at"] = _timestamp(self._clock())
            self._commit(candidate)

    def append_event(self, event: dict[str, Any], *, attempt_id: int | None = None,
                     collection: str = "events") -> str:
        if not isinstance(collection, str) or collection not in {"events", "checks", "tool_events"}:
            raise TaskRecordError("events belong to events, checks, or tool_events")
        if not isinstance(event, dict):
            raise TaskRecordError("event must be a JSON object")
        with self._lock:
            candidate = self._candidate()
            attempt = self._attempt(candidate, attempt_id)
            row = _clone(event)
            sequence = len(attempt[collection]) + 1
            event_id = f"{attempt['attempt_id']}:{collection}:{sequence}"
            row["event_id"] = event_id
            row["sequence"] = sequence
            row.setdefault("timestamp", _timestamp(self._clock()))
            attempt[collection].append(row)
            attempt["updated_at"] = _timestamp(self._clock())
            self._commit(candidate)
            return event_id

    def append_check(self, check: dict[str, Any], *, attempt_id: int | None = None) -> str:
        return self.append_event(check, attempt_id=attempt_id, collection="checks")

    def append_tool_event(self, event: dict[str, Any], *, attempt_id: int | None = None) -> str:
        return self.append_event(event, attempt_id=attempt_id, collection="tool_events")

    def set_attempt_feedback(self, feedback: Any, *, attempt_id: int | None = None,
                             destination: str = "return_to_caller") -> None:
        if not isinstance(destination, str) or destination not in {"return_to_caller", "sent_to_agent"}:
            raise TaskRecordError("feedback destination must be return_to_caller or sent_to_agent")
        with self._lock:
            candidate = self._candidate()
            attempt = self._attempt(candidate, attempt_id)
            if destination == "sent_to_agent":
                attempt["feedback"][destination].append(_clone(feedback))
            else:
                if attempt["feedback"][destination] is not None:
                    raise TaskRecordError("return_to_caller feedback is immutable")
                attempt["feedback"][destination] = feedback
            attempt["updated_at"] = _timestamp(self._clock())
            self._commit(candidate)

    def update(self, *, costs: dict[str, Any] | None = None, metadata: dict[str, Any] | None = None) -> None:
        with self._lock:
            candidate = self._candidate()
            if costs is not None:
                candidate["costs"].update(costs)
            if metadata is not None:
                candidate["metadata"].update(metadata)
            self._commit(candidate)

    def set_initial_state(self, state: Any) -> None:
        """Fill a deferred observed state exactly once; never rewrite history."""
        if state is None:
            raise TaskRecordError("initial state must contain an actual observation")
        with self._lock:
            candidate = self._candidate()
            if candidate["initial_state"] is not None:
                raise TaskRecordError("initial_state is immutable once observed")
            candidate["initial_state"] = state
            self._commit(candidate)

    def finish(self, *, final_state: Any, outcome: dict[str, Any], costs: dict[str, Any] | None = None,
               record_status: str = "COMPLETED") -> dict[str, Any]:
        if not isinstance(record_status, str) or record_status not in _TERMINAL:
            raise TaskRecordError("finish requires COMPLETED, FAILED, or ABORTED record_status")
        if not isinstance(outcome, dict) or not isinstance(outcome.get("status"), str):
            raise TaskRecordError("outcome must contain an actual status string")
        with self._lock:
            candidate = self._candidate()
            candidate.update(final_state=final_state, outcome=outcome, record_status=record_status,
                             finished_at=_timestamp(self._clock()))
            if costs is not None:
                candidate["costs"].update(costs)
            self._commit(candidate)
            return self.data

src/embodied_agent/execution/home_contra:
"""Finite home skill contract, independent of simulator and model services."""
from __future__ import annotations

import math
from typing import Any


class HomeExecutionError(ValueError):
    def __init__(self, code: str, message: str, evidence: dict[str, Any] | None = None):
        super().__init__(message)
        self.code = code
        self.evidence = evidence or {}


SKILL_PARAMETERS = {
    "observe": set(), "query_world": {"object_id"}, "inspect": {"object_id"},
    "navigate": {"target"}, "pick": {"object_id"}, "carry": {"target"},
    "place": {"support_id", "target_xy"}, "wait": {"seconds"}, "stop": set(),
}


def _finite(value: Any) -> bool:
    if type(value) not in (int, float):
        return False
    try:
        return math.isfinite(float(value))
    except (OverflowError, ValueError):
        return False


def validate_home_plan(payload: Any) -> list[dict[str, Any]]:
    if (not isinstance(payload, dict) or set(payload) != {"schema_version", "actions"}
            or type(payload["schema_version"]) is not int or payload["schema_version"] != 1):
        raise HomeExecutionError("INVALID_PLAN", "Expected home plan schema_version 1 and actions")
    actions = payload["actions"]
    if not isinstance(actions, list) or not 1 <= len(actions) <= 32:
        raise HomeExecutionError("INVALID_PLAN", "Plan requires 1..32 actions")
    validated = []
    for action in actions:
        if not isinstance(action, dict) or not isinstance(action.get("skill"), str):
            raise HomeExecutionError("INVALID_PLAN", "Every action requires a registered skill")
        skill = action["skill"]
        if skill not in SKILL_PARAMETERS:
            raise HomeExecutionError("UNREGISTERED_SKILL", f"Skill {skill!r} is unavailable")
        if set(action) != {"skill", *SKILL_PARAMETERS[skill]}:
            raise HomeExecutionError("INVALID_PLAN", f"Unexpected parameters for {skill}")
        for field in ("object_id", "target", "support_id"):
            if field in action and (not isinstance(action[field], str) or not action[field].strip()):
                raise HomeExecutionError("INVALID_PLAN", f"{field} requires an ID")
        value = dict(action)
        if skill == "place":
            point = action["target_xy"]
            if (not isinstance(point, (list, tuple)) or len(point) != 2
                    or any(not _finite(v) for v in point)):
                raise HomeExecutionError("INVALID_PLAN", "target_xy requires two finite metre coordinates")
            value["target_xy"] = list(point)
        if skill == "wait":
            seconds = action["seconds"]
            if not _finite(seconds) or not 0 <= seconds <= 10:
                raise HomeExecutionError("INVALID_PLAN", "Wait requires 0..10 seconds")
        validated.append(value)
    return validated

src/embodied_agent/execution/panda_adapt:
"""Panda mechanics behind the shared instruction/runtime interface."""
from __future__ import annotations

import copy
import hashlib
import math
import uuid
from typing import Any

import mujoco

from embodied_agent.contracts import ContractError
from embodied_agent.models.budget import current_budget
from embodied_agent.safety.path_precheck import check_skill_path
from embodied_agent.simulation.observations import make_observation


class PandaInstructionAdapter:
    robot_kind = "panda"

    def __init__(self, episode: Any, config: dict[str, Any]):
        self.episode, self.world, self.config = episode, episode.world, config
        self._obs_id = 0
        self.action_results: list[dict] = []
        self.placements: list[dict] = []
        self._permits: set[str] = set()
        self.episode.step_budget_limit = episode.total_steps + int(config["budgets"]["max_episode_steps"])
        episode.prepare()
        episode.hold("scene_settle", int(episode.thresholds["scene_settle_steps"]))
        initial = episode.postconditions()
        held = make_observation(episode, 0, []).held_estimate is True
        if not held and (not initial["table_supported"] or initial["cube_linear_speed_m_s"] > .01):
            raise ContractError("PRECONDITION_FAILED", "Object must be supported and settled before planning")

    def __getattr__(self, name):
        return getattr(self.episode, name)

    def observe(self) -> dict:
        ep = self.episode
        self._obs_id += 1
        measured = make_observation(ep, self._obs_id, [r["action"]["skill"] for r in self.action_results])
        position = ep.data.xpos[ep.cube_body_id].copy().tolist()
        targets = {}
        for key in self.world.targets:
            geom = ep.model.geom(key).id
            targets[key] = {"position_m": ep.data.geom_xpos[geom].tolist(),
                            "half_size_m": ep.model.geom_size[geom].tolist()}
        held = "cube" if measured.held_estimate is True else None
        return {"schema_kind": "desktop_snapshot", "map_id": self.world.map_id,
                "map_revision": self.world.revision, "world_version": ep.total_steps,
                "obs_id": self._obs_id, "sim_time_s": float(ep.data.time),
                "cube_xyz_m": position, "cube_position_m": position,
                "objects": {"cube": {"category": "cube", "position_m": position,
                    "half_size_m": ep.cube_half_size.tolist(), "mass_kg": float(ep.model.body_mass[ep.cube_body_id]),
                    "support": "gripper" if held else "table", "states": {},
                    "operations": ["inspect", "pick", "place"]}},
                "robot": {"held_object": held, "held_verified": measured.held_estimate,
                          "position_m": ep.data.site_xpos[ep.ee_site_id].tolist()},
                "targets": targets, "target_regions": targets,
                "danger_zone": self.world.danger_zone.to_dict(),
                "grasp_evidence": measured.cube,
                "evidence": self.evaluate_goal_evidence([])}

    def evaluate_goal_evidence(self, goals) -> dict:
        ep = self.episode
        placements = []
        previous_target = ep.target_geom_id
        try:
            for old in self.placements:
                ep.target_geom_id = ep.model.geom(old["target_id"]).id
                check = ep.postconditions()
                placements.append({**old, "passed": bool(old["passed"] and check["all_instantaneous_conditions"]),
                                   "predicates": check})
            # Verify already satisfied destinations with the same guarded,
            # per-step stable-window evaluator as a newly performed place.
            for goal in goals or []:
                target = goal.get("target_id")
                if (goal.get("predicate") not in {"supported_on", "inside"}
                        or goal.get("object_id") != "cube" or target not in self.world.targets
                        or any(p["target_id"] == target and p["passed"] for p in placements)):
                    continue
                ep.target_geom_id = ep.model.geom(target).id
                if ep.postconditions()["all_instantaneous_conditions"]:
                    stable_steps, measured = ep.verify_goal()
                    verified = {"object_id": "cube", "support_id": "table", "target_id": target,
                                "passed": True, "stable_window_passed": True,
                                "stable_steps": stable_steps, "predicates": measured,
                                "source": "independent_existing_state_verification"}
                    self.placements.append(verified)
                    placements.append(copy.deepcopy(verified))
        finally:
            ep.target_geom_id = previous_target
        check = ep.postconditions()
        side_count = len(ep.finger_contact_sides())
        return {"placements": placements, "action_results": copy.deepcopy(self.action_results),
                "objects": {"cube": {"released": bool(check["no_gripper_contact"]),
                                      "stable": bool(placements and any(p["passed"] for p in placements)),
                                      "finger_contact_side_count": side_count,
                                      "lift_verified": bool(ep.data.xpos[ep.cube_body_id][2] > ep.table_top_z + ep.cube_half_size[2] + .03),
                                      "robot_contact": not check["no_gripper_contact"],
                                      "supports": ["table"] if check["table_supported"] else []}},
                "performed_methods": ["controlled_place"] if placements else []}

    def action_satisfied(self, action: dict, previous: dict) -> bool:
        if action.get("skill") == "pick":
            return self.observe()["robot"]["held_verified"] is True
        if action.get("skill") == "place":
            return any(row["target_id"] == action.get("target_id") and row["passed"]
                       for row in self.evaluate_goal_evidence([])["placements"])
        return False

    def _fingerprint(self) -> str:
        ep = self.episode
        return hashlib.sha256(ep.data.qpos.tobytes() + ep.data.qvel.tobytes() +
                              ep.data.geom_xpos.tobytes() + ep.model.geom_size.tobytes() +
                              ep.model.geom_pos.tobytes() + ep.data.ctrl.tobytes() +
                              ep.data.mocap_pos.tobytes() + ep.data.mocap_quat.tobytes()).hexdigest()

    def review_next_action(self, action: dict) -> dict:
        if not isinstance(action, dict):
            raise ContractError("INVALID_PLAN", "Action must be an object")
        ep = self.episode
        skill = action.get("skill")
        shapes = {"pick": [{"skill", "object_id"}, {"skill", "object_id", "approach_mode"}],
                  "place": [{"skill", "target_id"}], "stop": [{"skill"}], "wait": [{"skill", "seconds"}]}
        if skill not in shapes or set(action) not in shapes[skill]:
            raise ContractError("INVALID_PLAN", "Unsupported Panda action parameters")
        observation = self.observe()
        path = None
        if skill == "pick":
            if action["object_id"] not in observation["objects"] or action.get("approach_mode", "top") != "top":
                raise ContractError("UNSUPPORTED_SKILL", "Panda top grasp requires a currently observed manipulable object")
            if observation["robot"]["held_verified"] is not False:
                raise ContractError("PRECONDITION_FAILED", "Pick requires measured empty-hand state")
        elif skill == "place":
            target = action["target_id"]
            if target not in self.world.targets:
                raise ContractError("UNKNOWN_TARGET", "Destination is not in the current region catalogue")
            if observation["robot"]["held_verified"] is not True:
                raise ContractError("PRECONDITION_FAILED", "Place requires measured bilateral holding")
            ep.target_geom_id = ep.model.geom(target).id
            ep.target_center = ep.data.geom_xpos[ep.target_geom_id].copy()
        elif skill == "wait":
            seconds = action["seconds"]
            if type(seconds) not in (int, float) or not math.isfinite(seconds) or not 0 <= seconds <= 10:
                raise ContractError("INVALID_PLAN", "Wait requires finite 0–10 seconds")
        if skill in {"pick", "place"}:
            path = check_skill_path(ep, skill, self.config)
        permit = uuid.uuid4().hex
        self._permits.add(permit)
        return {"action": copy.deepcopy(action), "state": self._fingerprint(), "path": path,
                "map_revision": self.world.revision, "permit": permit}

    def run_action(self, action: dict, *, record_event=None) -> dict:
        ep = self.episode
        started = ep.total_steps
        invoked = False
        try:
            review = self.review_next_action(action)
            if review["state"] != self._fingerprint() or review["map_revision"] != self.world.revision:
                raise ContractError("STALE_ACTION", "State changed after execution review")
            if record_event:
                record_event("action_review", {"action": action, "review": review}, self.observe())
                record_event("skill_started", {"action": action}, self.observe())
            budget = current_budget()
            if budget is not None:
                budget.check()
            if (review["permit"] not in self._permits or review["state"] != self._fingerprint()
                    or review["map_revision"] != self.world.revision):
                raise ContractError("STALE_ACTION", "Reviewed action state changed or permit was consumed")
            self._permits.remove(review["permit"])
            invoked = True
            if action["skill"] == "pick":
                start_z = float(ep.data.xpos[ep.cube_body_id][2])
                metrics = ep.pick_skill()
                grasp = self.evaluate_goal_evidence([])["objects"]["cube"]
                grasp.update(held_verified=self.observe()["robot"]["held_verified"],
                             achieved_lift_m=float(ep.data.xpos[ep.cube_body_id][2]) - start_z)
                evidence = {"skill": metrics, "grasp": grasp}
            elif action["skill"] == "place":
                evidence = ep.place_skill()
                stable_steps, check = ep.verify_goal()
                if not check["all_instantaneous_conditions"]:
                    raise ContractError("GOAL_NOT_MET", "Measured stable placement did not meet region goal")
                self.placements.append({"object_id": "cube", "support_id": "table", "target_id": action["target_id"],
                                        "passed": True, "stable_window_passed": True,
                                        "stable_steps": stable_steps, "predicates": check})
                evidence = {"skill": evidence, "placement": self.placements[-1]}
            else:
                evidence = self.hold(seconds=float(action.get("seconds", .1)))
            if action["skill"] == "pick" and self.observe()["robot"]["held_verified"] is not True:
                raise ContractError("GRASP_EMPTY", "Grasp lacks actual bilateral contact and lift")
            self.action_results.append({"action": copy.deepcopy(action), "success": True, "result": evidence})
            result = {"status": "SUCCESS", "action": action, "evidence": evidence,
                      "physics_steps": ep.total_steps - started, "executed": True, "observation": self.observe()}
            if record_event:
                record_event("post_skill_passed", {"action": action, "skill_result": result}, result["observation"])
            return result
        except Exception as exc:
            cleanup = []
            try:
                self.safe_stop()
            except Exception as stop_exc:
                cleanup.append({"stage": "safe_stop", "message": str(stop_exc)})
            try:
                observation = self.observe()
            except Exception as observation_exc:
                observation = None
                cleanup.append({"stage": "observation", "message": str(observation_exc)})
            result = {"status": "ABORTED" if type(exc).__name__ in {"ViewerClosed"} else "FAILED",
                      "action": action, "error_code": getattr(exc, "code", type(exc).__name__),
                      "error_message": str(exc), "error_evidence": getattr(exc, "details", {}),
                      "physics_steps": ep.total_steps - started, "executed": invoked,
                      "observation": observation, "cleanup_errors": cleanup,
                      "stop_failed": any(e["stage"] == "safe_stop" for e in cleanup)}
            if record_event:
                record_event("execution_failed", result, observation)
            return result

    def hold(self, seconds=.02) -> dict:
        ep = self.episode
        steps = max(1, math.ceil(seconds / ep.model.opt.timestep))
        ep.hold("instruction_hold", steps)
        return {"sim_time_s": float(ep.data.time), "held_side_count": len(ep.finger_contact_sides())}

    def safe_stop(self) -> dict:
        ep = self.episode
        callback = getattr(ep, "on_frame", None)
        limit = ep.step_budget_limit
        ep.on_frame = None
        try:
            ep.step_budget_limit = max(limit, ep.total_steps + math.ceil(.1 / ep.model.opt.timestep))
            ep.data.mocap_pos[ep.mocap_id] = ep.data.site_xpos[ep.ee_site_id]
            mujoco.mju_mat2Quat(ep.data.mocap_quat[ep.mocap_id], ep.data.site_xmat[ep.ee_site_id])
            return self.hold(seconds=.1)
        finally:
            ep.step_budget_limit = limit
            ep.on_frame = callback

