"""Pure geometry candidates for the Stretch side gripper and support surfaces.

Candidates describe poses, never move a robot or claim a successful grasp. The
live adapter still checks reach, routes, permissions and physical contacts.
"""
from __future__ import annotations

import math
import hashlib
from dataclasses import dataclass
from typing import Any, Mapping

from .schema import WorldError, finite_vector

SIDE_GRASP_X_M = -.021385
SIDE_GRASP_REACH_OFFSET_M = .34836
EXTENSION_RANGE_M = (.06, .49)
LIFT_RANGE_M = (-.5, .6)
MAX_PLACE_SURFACE_HEIGHT_M = .98


@dataclass(frozen=True)
class SupportSurface:
    surface_id: str
    position_m: tuple[float, float, float]
    half_size_m: tuple[float, float, float]
    top_z: float
    geom_names: tuple[str, ...]
    kind: str = "horizontal"


def lookup_surface(world: Any, surface_id: str) -> SupportSurface:
    if surface_id == "floor":
        width, depth, _ = world.room.size_m
        return SupportSurface("floor", (0., 0., 0.), (width / 2, depth / 2, 0.), 0., ("home_floor",), "floor")
    item = world.furniture.get(surface_id)
    if item is None:
        raise WorldError("UNKNOWN_SUPPORT", f"Unknown support {surface_id}")
    position, half = item.position_m, item.half_size_m
    if item.shape_kind == "sofa":
        # The seat is below the arms/back. Only the unobstructed seat rectangle
        # is a placing surface; furniture bounding-box top is not a surface.
        position = (position[0], position[1] - .07, item.top_z / 2)
        half = (max(.001, half[0] - .14), max(.001, half[1] - .07), item.top_z / 2)
    return SupportSurface(surface_id, position, half, item.top_z, item.geom_names, item.shape_kind)


def grasp_supported(obj: Any) -> bool:
    return (.019 <= obj.half_size_m[0] <= .030 and
            .019 <= obj.half_size_m[1] <= .030 and
            .019 <= obj.half_size_m[2] <= .035 and obj.mass_kg <= .15)


def _free_dock(world: Any, xy: tuple[float, float], positions: Mapping[str, Any], *, object_id: str | None = None) -> bool:
    # Leave room for the actual retracted hand and a carried box, rather than
    # docking at a pose from which the measured transport footprint cannot leave.
    radius = max(world.navigation.robot_radius_m, .48)
    if any(abs(xy[i]) + radius >= world.room.size_m[i] / 2 for i in (0, 1)):
        return False
    for item in world.furniture.values():
        dx = max(abs(xy[0] - item.position_m[0]) - item.half_size_m[0], 0.)
        dy = max(abs(xy[1] - item.position_m[1]) - item.half_size_m[1], 0.)
        if dx <= radius + .025 and dy <= radius + .025:
            return False
    for name, obj in world.objects.items():
        if name == object_id:
            continue
        position = positions.get(name, obj.position_m)
        if position[2] - obj.half_size_m[2] < .15 and math.dist(xy, position[:2]) <= radius + max(obj.half_size_m[:2]) + .025:
            return False
    return True


def _target_free(world: Any, support: SupportSurface, xy: tuple[float, float], positions: Mapping[str, Any], object_id: str | None) -> bool:
    obj = world.objects.get(object_id)
    half = obj.half_size_m if obj is not None else (.025, .025, .025)
    margin = .05 if obj is not None and "fragile" in obj.risk_tags else .025
    if any(abs(xy[i] - support.position_m[i]) + half[i] + margin > support.half_size_m[i] for i in (0, 1)):
        return False
    position = (*xy, support.top_z + half[2])
    if support.surface_id == "floor":
        for item in world.furniture.values():
            if all(abs(xy[i] - item.position_m[i]) < half[i] + item.half_size_m[i] + .03 for i in (0, 1)):
                return False
    for name, other in world.objects.items():
        if name != object_id and all(abs(position[i] - positions.get(name, other.position_m)[i]) < half[i] + other.half_size_m[i] + .025 for i in range(3)):
            return False
    if obj is not None and world.action_violations("place", object_id, target_position_m=position, object_positions=positions):
        return False
    return True


def _placement_targets(world: Any, surface: SupportSurface) -> tuple[tuple[float, float], ...]:
    if surface.surface_id == "floor":
        return ((0., -.65), (0., 0.), (-.7, -.9), (.7, -.9), (0., -1.7),
                (-1.5, -.9), (1.5, -.9), (-.8, 1.8), (.8, 1.8))
    x, y, _ = surface.position_m
    hx, hy, _ = surface.half_size_m
    if surface.kind == "sofa":
        return tuple((x + fraction * max(0., hx - .12), y - max(0., hy - .12))
                     for fraction in (0., -.5, .5))
    # Edge lanes bring a broad support within the telescope envelope. Interior
    # targets are also considered for small surfaces, without fixed object IDs.
    return tuple(dict.fromkeys((
        (x + sx * max(0., hx - .12), y + sy * max(0., hy - .12))
        for sx, sy in ((0, -1), (-.5, -1), (.5, -1), (0, 1), (-1, 0), (1, 0), (0, 0)))))


def candidate_operation_points(world: Any, *, object_id: str | None = None,
                               support_id: str | None = None, target_xy: Any = None,
                               object_positions: Mapping[str, Any] | None = None) -> tuple[Any, ...]:
    from .home_schema import HomeOperationPoint

    positions = {key: finite_vector((object_positions or {}).get(key, obj.position_m), key)
                 for key, obj in world.objects.items()}
    picking = object_id is not None and support_id is None
    if picking:
        if object_id not in world.objects:
            raise WorldError("UNKNOWN_OBJECT", str(object_id))
        obj = world.objects[object_id]
        if not grasp_supported(obj):
            return ()
        position = positions[object_id]
        if not -.5 <= position[2] - .512 <= .45:
            return ()
        support_id = world.support_at(object_id, position)
        if support_id is None:
            return ()
        targets = (position[:2],)
    else:
        support_id = support_id or "floor"
        surface = lookup_surface(world, support_id)
        if not 0 <= surface.top_z <= MAX_PLACE_SURFACE_HEIGHT_M:
            return ()
        if target_xy is not None:
            if not isinstance(target_xy, (list, tuple)) or len(target_xy) != 2:
                raise WorldError("INVALID_TARGET", "target_xy must contain two finite coordinates")
            targets = (finite_vector((*target_xy, 0.), "target_xy")[:2],)
        else:
            targets = _placement_targets(world, surface)
        targets = tuple(xy for xy in targets if _target_free(world, surface, xy, positions, object_id))
    points = []
    surface = lookup_surface(world, support_id)
    for ti, xy in enumerate(targets):
        for yi, yaw in enumerate((math.pi, 0., math.pi / 2, -math.pi / 2)):
            # Raised arms/back obstruct side and rear approaches below their
            # height. Front access is geometrically distinct from a plain box.
            if surface.kind == "sofa" and yaw != math.pi:
                continue
            cosine, sine = math.cos(yaw), math.sin(yaw)
            # Keep several centimetres of extension for measured closed-grasp
            # alignment; a geometric endpoint at the actuator limit cannot
            # compensate for payload deflection or a different grasp offset.
            for ri, reach in enumerate((.70, .76, .62, .80)):
                local = (SIDE_GRASP_X_M, -reach)
                dock = (xy[0] - cosine * local[0] + sine * local[1],
                        xy[1] - sine * local[0] - cosine * local[1])
                if not _free_dock(world, dock, positions, object_id=object_id):
                    continue
                geometry_key = f"{xy[0]:.6f},{xy[1]:.6f},{yaw:.6f},{reach:.6f}"
                identifier = f"auto_{object_id if picking else support_id}_{hashlib.sha256(geometry_key.encode()).hexdigest()[:12]}"
                points.append(HomeOperationPoint(identifier, (*dock, 0.), yaw, support_id,
                    (object_id,) if picking else (), tuple(xy)))
    # Preserve registered poses when they genuinely reach the measured target.
    for point in world.operation_points.values():
        if point.support != support_id or not _free_dock(world, point.position_m[:2], positions, object_id=object_id):
            continue
        if picking:
            dx, dy = targets[0][0] - point.position_m[0], targets[0][1] - point.position_m[1]
            local = (math.cos(point.yaw_rad) * dx + math.sin(point.yaw_rad) * dy,
                     -math.sin(point.yaw_rad) * dx + math.cos(point.yaw_rad) * dy)
            if abs(local[0] - SIDE_GRASP_X_M) > .018 or not .06 <= -local[1] - SIDE_GRASP_REACH_OFFSET_M <= .49:
                continue
            points.insert(0, point)
        elif point.target_xy_m is not None and point.target_xy_m in targets:
            points.insert(0, point)
    return tuple({point.point_id: point for point in points}.values())


def compute_pick_candidates(world: Any, snapshot: dict, object_id: str) -> tuple[Any, ...]:
    positions = {key: item["position_m"] for key, item in snapshot.get("objects", {}).items()}
    return candidate_operation_points(world, object_id=object_id, object_positions=positions)


def resolve_navigation_target(world: Any, snapshot: dict, target: str) -> Any:
    """Resolve registered/generated poses or current object/support IDs.

    Route selection belongs to the live executor; callers can inspect all
    candidates and choose a reachable route instead of trusting this ordering.
    """
    if target in world.operation_points and not target.startswith("auto_"):
        return world.operation_points[target]
    positions = {key: item["position_m"] for key, item in snapshot.get("objects", {}).items()}
    if target in world.objects:
        points = candidate_operation_points(world, object_id=target, object_positions=positions)
    elif target == "floor" or target in world.furniture:
        points = candidate_operation_points(world, support_id=target, object_positions=positions)
    else:
        points = tuple(point for name in (*world.objects, *world.furniture, "floor")
                       for point in candidate_operation_points(world, **({"object_id": name} if name in world.objects else {"support_id": name}), object_positions=positions)
                       if point.point_id == target)
    if not points:
        raise WorldError("UNREACHABLE_TARGET", f"No collision-free manipulation dock for {target}")
    robot_xy = snapshot.get("robot", {}).get("position_m", world.navigation.initial_position_m)[:2]
    return min(points, key=lambda point: (math.dist(robot_xy, point.position_m[:2]), point.point_id))


def generate_operation_points(world: Any) -> dict[str, Any]:
    """Small deterministic registry for maps that omit manual docking poses."""
    points = {}
    for object_id in world.objects:
        for point in candidate_operation_points(world, object_id=object_id)[:4]:
            points[point.point_id] = point
    for support_id in (*world.furniture, "floor"):
        # Include different target lanes, not merely four extensions at one xy.
        seen = set()
        for point in candidate_operation_points(world, support_id=support_id):
            if point.target_xy_m in seen:
                continue
            seen.add(point.target_xy_m)
            points[point.point_id] = point
            if len(seen) >= 4:
                break
    return dict(list(points.items())[:128])

src/embodied_agent/maps/schema.py:
"""Pure map schema and conservative initial-scene validation.

Distances are metres and box sizes are *half extents*, matching MuJoCo.
Maps describe initial conditions only; running a robot never writes a map.
"""

from __future__ import annotations

import json
import math
import re
from dataclasses import dataclass
from types import MappingProxyType
from typing import Any, Mapping


TABLE_CENTER = (0.55, 0.0)
TABLE_HALF_SIZE = (0.38, 0.38)
TABLE_TOP_Z = 0.4
CUBE_HALF_SIZE = 0.025
MAP_ID_PATTERN = re.compile(r"[a-z][a-z0-9_-]{0,63}\Z")


class WorldError(ValueError):
    def __init__(self, code: str, message: str):
        super().__init__(message)
        self.code = code


def _exact_keys(value: Any, keys: set[str], label: str) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != keys:
        raise WorldError("INVALID_MAP", f"{label} must contain exactly {sorted(keys)}")
    return value


def finite_vector(value: Any, label: str) -> tuple[float, float, float]:
    if not isinstance(value, (tuple, list)) or len(value) != 3:
        raise WorldError("INVALID_MAP", f"{label} requires three coordinates in metres")
    if any(isinstance(item, bool) or not isinstance(item, (int, float)) for item in value):
        raise WorldError("INVALID_MAP", f"{label} requires numbers, not strings or booleans")
    try:
        result = tuple(float(item) for item in value)
    except (OverflowError, ValueError) as exc:
        raise WorldError("INVALID_MAP", f"{label} requires finite, representable numbers") from exc
    if not all(math.isfinite(item) for item in result):
        raise WorldError("INVALID_MAP", f"{label} requires finite numbers")
    return result


def _on_table(position: tuple[float, ...], half: tuple[float, ...], label: str) -> None:
    for axis in (0, 1):
        if abs(position[axis] - TABLE_CENTER[axis]) + half[axis] > TABLE_HALF_SIZE[axis] + 1e-9:
            raise WorldError("INVALID_MAP", f"{label} extends outside the tabletop support area")


def strict_json(raw: str) -> dict[str, Any]:
    def pairs(items: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in items:
            if key in result:
                raise WorldError("INVALID_JSON", f"Duplicate JSON key: {key}")
            result[key] = value
        return result

    def reject_constant(value: str) -> None:
        raise WorldError("INVALID_JSON", f"Non-finite JSON constant: {value}")

    try:
        payload = json.loads(raw, object_pairs_hook=pairs, parse_constant=reject_constant)
    except WorldError:
        raise
    except (ValueError, RecursionError) as exc:
        raise WorldError("INVALID_JSON", "Expected one well-formed JSON object") from exc
    if not isinstance(payload, dict):
        raise WorldError("INVALID_JSON", "Expected one JSON object")
    return payload


@dataclass(frozen=True)
class BoxRegion:
    position_m: tuple[float, float, float]
    half_size_m: tuple[float, float, float]

    @classmethod
    def from_dict(cls, payload: dict[str, Any], label: str) -> "BoxRegion":
        _exact_keys(payload, {"position_m", "half_size_m"}, label)
        position = finite_vector(payload["position_m"], f"{label}.position_m")
        half = finite_vector(payload["half_size_m"], f"{label}.half_size_m")
        if any(value <= 0 for value in half):
            raise WorldError("INVALID_MAP", f"{label}.half_size_m must be positive")
        return cls(position, half)

    def to_dict(self) -> dict[str, Any]:
        return {"position_m": list(self.position_m), "half_size_m": list(self.half_size_m)}


@dataclass(frozen=True)
class WorldMap:
    schema_version: int
    map_id: str
    name: str
    description: str
    revision: int
    cube_position_m: tuple[float, float, float]
    danger_zone: BoxRegion
    targets: Mapping[str, BoxRegion]

    @classmethod
    def from_dict(cls, payload: dict[str, Any]) -> "WorldMap":
        _exact_keys(payload, {
            "schema_version", "map_id", "name", "description", "revision",
            "cube_position_m", "danger_zone", "targets",
        }, "world")
        if type(payload["schema_version"]) is not int or payload["schema_version"] != 1:
            raise WorldError("INVALID_MAP", "Only map schema_version 1 is supported")
        map_id = payload["map_id"]
        if not isinstance(map_id, str) or not MAP_ID_PATTERN.fullmatch(map_id):
            raise WorldError("INVALID_MAP_ID", "Map ID must use lowercase letters, digits, underscores or hyphens")
        for label, limit in (("name", 100), ("description", 1000)):
            value = payload[label]
            if not isinstance(value, str) or len(value) > limit or (label == "name" and not value.strip()):
                raise WorldError("INVALID_MAP", f"Invalid map {label}")
        revision = payload["revision"]
        if type(revision) is not int or revision < 0:
            raise WorldError("INVALID_MAP", "revision must be a nonnegative integer")
        cube = finite_vector(payload["cube_position_m"], "cube_position_m")
        _on_table(cube, (CUBE_HALF_SIZE,) * 3, "cube")
        if abs(cube[2] - (TABLE_TOP_Z + CUBE_HALF_SIZE)) > 0.001:
            raise WorldError("INVALID_MAP", "Cube centre z must be 0.425 m (resting on the tabletop)")
        danger = BoxRegion.from_dict(payload["danger_zone"], "danger_zone")
        _on_table(danger.position_m, danger.half_size_m, "danger_zone")
        if danger.position_m[2] - danger.half_size_m[2] < 0 or danger.position_m[2] + danger.half_size_m[2] > 1.5:
            raise WorldError("INVALID_MAP", "Danger-zone vertical extent must remain between 0 and 1.5 m")
        target_data = payload["targets"]
        if not isinstance(target_data, dict) or not 1 <= len(target_data) <= 64:
            raise WorldError("INVALID_MAP", "targets requires 1–64 named regions")
        for target_id in target_data:
            if (not isinstance(target_id, str) or not MAP_ID_PATTERN.fullmatch(target_id)
                    or target_id in {"danger_zone", "table_top", "cube", "cube_geom", "floor"}):
                raise WorldError("INVALID_MAP", "Target region ID is invalid or reserved")
        targets = {name: BoxRegion.from_dict(value, name) for name, value in target_data.items()}
        for name, region in targets.items():
            _on_table(region.position_m, region.half_size_m, name)
            if any(value < CUBE_HALF_SIZE + 0.002 for value in region.half_size_m[:2]):
                raise WorldError("INVALID_MAP", f"{name} must be large enough to contain the cube")
            if not 0 < region.half_size_m[2] <= 0.005:
                raise WorldError("INVALID_MAP", f"{name} is a thin tabletop marker; z half-size must be <= 0.005 m")
            if abs(region.position_m[2] - region.half_size_m[2] - TABLE_TOP_Z) > 1e-6:
                raise WorldError("INVALID_MAP", f"{name} bottom must coincide with the tabletop z=0.4 m")
        return cls(1, map_id, payload["name"], payload["description"], revision, cube, danger, MappingProxyType(targets))

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": self.schema_version, "map_id": self.map_id,
            "name": self.name, "description": self.description, "revision": self.revision,
            "cube_position_m": list(self.cube_position_m), "danger_zone": self.danger_zone.to_dict(),
            "targets": {name: region.to_dict() for name, region in self.targets.items()},
        }

src/embodied_agent/maps/unified_store.py:
"""The existing Demo's map catalog, preserving each domain's own schema."""
from __future__ import annotations

from pathlib import Path
from typing import Any

from embodied_agent.maps.home_schema import HomeWorld
from embodied_agent.maps.home_store import HomeMapStore
from embodied_agent.maps.schema import WorldError, WorldMap, strict_json
from embodied_agent.maps.store import DEFAULT_MAPS_DIR, MapStore

DemoWorld = HomeWorld | WorldMap


def parse_demo_world(payload: dict[str, Any]) -> DemoWorld:
    return HomeWorld.from_dict(payload) if payload.get("schema_kind") == "home" else WorldMap.from_dict(payload)


class UnifiedMapStore:
    """One catalog for map selection; storage retains revision checks by type."""
    def __init__(self, root: str | Path = DEFAULT_MAPS_DIR):
        self.root = Path(root).resolve()
        self.desktop = MapStore(self.root)
        self.home = HomeMapStore(self.root)

    def load(self, map_id: str) -> DemoWorld:
        path = self.desktop._path(map_id)
        try:
            if path.stat().st_size > 262144:
                raise WorldError("INVALID_MAP", "Map exceeds the supported domain size limit")
            payload = strict_json(path.read_text(encoding="utf-8"))
        except FileNotFoundError as exc:
            raise WorldError("MAP_NOT_FOUND", f"Map {map_id!r} does not exist") from exc
        if payload.get("schema_kind") != "home" and path.stat().st_size > 65536:
            raise WorldError("INVALID_MAP", "Desktop map exceeds 64 KiB")
        world = parse_demo_world(payload)
        if world.map_id != map_id:
            raise WorldError("INVALID_MAP", "Map ID must match its filename")
        return world

    def list_maps(self) -> list[DemoWorld]:
        return [self.load(path.stem) for path in sorted(self.root.glob("*.json"))] if self.root.exists() else []

    def save(self, world: DemoWorld, expected_revision: int | None = None) -> DemoWorld:
        if isinstance(world, HomeWorld):
            return self.home.save(world, expected_revision)
        if isinstance(world, WorldMap):
            return self.desktop.save(world, expected_revision)
        raise WorldError("INVALID_MAP", "Demo maps must use a registered domain schema")

src/embodied_agent/memory/store.py:
"""Thread-safe in-process memory, independent of models and simulation.

Memory is auxiliary data, never authority, a current observation, or verified
execution feedback. The caller supplies namespaces and explicitly writes trusted
result summaries. This store neither infers success nor calls external services.
The entry limit applies to the entire store; oldest writes are evicted first.
"""
from __future__ import annotations

from collections import OrderedDict
from copy import deepcopy
import json
import re
import threading
from typing import Any


_CREDENTIAL_KEYS = {"api_key", "apikey", "password", "passwd", "access_token",
                    "refresh_token", "client_secret", "private_key", "authorization"}
_PRIVATE_KEY = re.compile(r"-----BEGIN (?:RSA |EC |DSA |OPENSSH |ENCRYPTED )?PRIVATE KEY-----")
_ENGLISH_STOPWORDS = {"a", "an", "the", "and", "or", "to", "of", "in", "on", "for", "is", "are"}
_MARKER = "…[truncated]"


def _clone_data(value: Any) -> Any:
    """Accept JSON data and reject explicit credential fields/private key blocks.

    This is a narrow credential guard, not a classifier for arbitrary text.
    Callers must avoid including secrets in task summaries in the first place.
    Normal training metadata such as token_usage and max_tokens is permitted.
    """
    def check(item: Any) -> None:
        if isinstance(item, dict):
            for key, child in item.items():
                if not isinstance(key, str):
                    raise ValueError("Memory object keys must be strings")
                if key.lower().replace("-", "_") in _CREDENTIAL_KEYS and child not in (None, "", "[REDACTED]"):
                    raise ValueError("Credential fields cannot be stored in auxiliary memory")
                check(child)
        elif isinstance(item, (list, tuple)):
            for child in item:
                check(child)
        elif isinstance(item, str) and _PRIVATE_KEY.search(item):
            raise ValueError("Private keys cannot be stored in auxiliary memory")

    try:
        encoded = json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    except (TypeError, ValueError, RecursionError) as error:
        raise ValueError("Memory values must be finite JSON data") from error
    check(value)
    return json.loads(encoded)


def _identifier(value: str, name: str) -> str:
    if not isinstance(value, str) or not value.strip() or len(value) > 256:
        raise ValueError(f"{name} must contain 1..256 characters")
    return value


def _count(value: int, name: str) -> int:
    if type(value) is not int or value < 0:
        raise ValueError(f"{name} must be a nonnegative integer")
    return value


def _tokens(text: str, *, query: bool = False) -> set[str]:
    words = set(re.findall(r"[a-z0-9]+", text.lower())) - _ENGLISH_STOPWORDS
    for segment in re.findall(r"[\u3400-\u9fff]+", text):
        if not query or len(segment) == 1:
            words.update(segment)
        if len(segment) > 1:
            words.update(segment[index:index + 2] for index in range(len(segment) - 1))
    return words


def _size(value: Any) -> int:
    return len(json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":")))


def _budget_entry(entry: dict, remaining: int) -> dict | None:
    if _size(entry) <= remaining:
        return entry
    # Structured values are indivisible: a prefix must not masquerade as a
    # different complete result. Text excerpts are explicitly marked instead.
    if not isinstance(entry["value"], str):
        return None
    clipped = deepcopy(entry)
    clipped["truncated"] = True
    low, high = 0, len(entry["value"])
    best = None
    while low <= high:
        middle = (low + high) // 2
        clipped["value"] = entry["value"][:middle] + _MARKER
        if _size(clipped) <= remaining:
            best = deepcopy(clipped)
            low = middle + 1
        else:
            high = middle - 1
    return best


class MemoryStore:
    """Explicit namespaces, monotonic namespace revisions and copied JSON data."""

    def __init__(self, max_entries: int = 128):
        if type(max_entries) is not int or max_entries <= 0:
            raise ValueError("max_entries must be a positive integer")
        self._max_entries = max_entries
        self._entries: OrderedDict[tuple[str, str], dict] = OrderedDict()
        self._revisions: dict[str, int] = {}
        self._lock = threading.RLock()

    @property
    def max_entries(self) -> int:
        return self._max_entries

    def _next_revision(self, namespace: str) -> int:
        revision = self._revisions.get(namespace, 0) + 1
        self._revisions[namespace] = revision
        return revision

    def write(self, namespace: str, key: str, value: Any, *, metadata: dict | None = None) -> dict:
        namespace, key = _identifier(namespace, "namespace"), _identifier(key, "key")
        if metadata is not None and not isinstance(metadata, dict):
            raise ValueError("metadata must be a JSON object")
        content, annotations = _clone_data(value), _clone_data(metadata or {})
        with self._lock:
            revision = self._next_revision(namespace)
            entry = {"namespace": namespace, "key": key, "revision": revision,
                     "value": content, "metadata": annotations}
            identity = (namespace, key)
            self._entries.pop(identity, None)
            self._entries[identity] = entry
            while len(self._entries) > self.max_entries:
                (evicted_namespace, _), _ = self._entries.popitem(last=False)
                if evicted_namespace != namespace:
                    self._next_revision(evicted_namespace)
            return deepcopy(entry)

    def read(self, namespace: str, key: str) -> dict | None:
        namespace, key = _identifier(namespace, "namespace"), _identifier(key, "key")
        with self._lock:
            return deepcopy(self._entries.get((namespace, key)))

    def snapshot(self, namespace: str) -> dict:
        namespace = _identifier(namespace, "namespace")
        with self._lock:
            return {"namespace": namespace, "revision": self._revisions.get(namespace, 0),
                    "entries": deepcopy([entry for (scope, _), entry in self._entries.items()
                                         if scope == namespace])}

    def search(self, namespace: str, query: str, *, limit: int = 8, max_chars: int = 4000) -> dict:
        """Rank lexical matches; budget is compact JSON characters of entries.

        Empty/irrelevant queries return no entries. Structured values that do
        not fit are omitted intact; string excerpts include a truncation marker.
        Metadata, keys and the score consume the same visible-content budget.
        """
        limit, max_chars = _count(limit, "limit"), _count(max_chars, "max_chars")
        if not isinstance(query, str):
            raise ValueError("query must be a string")
        snapshot = self.snapshot(namespace)
        query_tokens = _tokens(query, query=True)
        ranked = []
        if query_tokens and limit and max_chars:
            for entry in snapshot["entries"]:
                visible = entry["key"] + " " + json.dumps(
                    {"value": entry["value"], "metadata": entry["metadata"]}, ensure_ascii=False)
                matched = query_tokens & _tokens(visible)
                if not matched:
                    continue
                row = {**entry, "score": len(matched) / len(query_tokens), "truncated": False,
                       "original_chars": len(entry["value"]) if isinstance(entry["value"], str)
                       else _size(entry["value"])}
                ranked.append(row)
        ranked.sort(key=lambda row: (-row["score"], row["key"]))
        entries, used, omitted = [], 0, 0
        for row in ranked:
            if len(entries) >= limit:
                break
            visible_row = _budget_entry(row, max_chars - used)
            if visible_row is None:
                omitted += 1
                continue
            entries.append(visible_row)
            used += _size(visible_row)
        return {"namespace": snapshot["namespace"], "revision": snapshot["revision"],
                "query": query, "entries": entries, "max_chars": max_chars,
                "returned_chars": used, "omitted_count": omitted}

    def clear(self, namespace: str) -> dict:
        namespace = _identifier(namespace, "namespace")
        with self._lock:
            identities = [identity for identity in self._entries if identity[0] == namespace]
            for identity in identities:
                del self._entries[identity]
            return {"namespace": namespace, "revision": self._next_revision(namespace),
                    "removed_count": len(identities)}

src/embodied_agent/models/budget.py:
"""One thread-safe budget and cancellation signal for the entire user task."""
from __future__ import annotations

from contextlib import contextmanager
from contextvars import ContextVar
import threading
import time
import math
from typing import Any, Callable

from .contracts import PlannerError


class TaskBudget:
    def __init__(self, config: dict[str, Any] | None = None, *, clock: Callable = time.monotonic):
        limits = (config or {}).get("task_budget", config or {})
        self.max_requests = int(limits.get("max_requests", 24))
        self.max_tokens = int(limits.get("max_tokens", 131072))
        self.max_actions = int(limits.get("max_actions", 128))
        self.max_replans = int(limits.get("max_replans", 4))
        self.timeout_s = float(limits.get("timeout_s", 300))
        if min(self.max_requests, self.max_tokens, self.max_actions) < 1 or self.max_replans < 0 or not math.isfinite(self.timeout_s) or self.timeout_s <= 0:
            raise ValueError("Task budget limits must be positive; max_replans may be zero")
        self._clock, self._started = clock, clock()
        self._lock = threading.RLock()
        self.cancel_reason: str | None = None
        self.cancel_code = "TASK_CANCELLED"
        self.requests = self.prompt_tokens = self.completion_tokens = 0
        self.actions = self.replans = 0

    def cancel(self, reason: str = "Task cancelled", *, code: str = "TASK_CANCELLED") -> None:
        with self._lock:
            if self.cancel_reason is None:
                self.cancel_reason, self.cancel_code = reason, code

    def check(self) -> None:
        with self._lock:
            if self.cancel_reason:
                raise PlannerError(self.cancel_code, self.cancel_reason, {"budget": self.snapshot()})
            if self.remaining_s <= 0:
                raise PlannerError("TASK_BUDGET_EXCEEDED", "Task wall-clock budget exhausted", {"budget": self.snapshot()})
            if self.prompt_tokens + self.completion_tokens >= self.max_tokens:
                raise PlannerError("TASK_BUDGET_EXCEEDED", "Task token budget exhausted", {"budget": self.snapshot()})

    @property
    def remaining_s(self) -> float:
        return max(0.0, self.timeout_s - (self._clock() - self._started))

    def output_limit(self, requested: int) -> int:
        with self._lock:
            self.check()
            return min(requested, self.max_tokens - self.prompt_tokens - self.completion_tokens)

    def record_request(self) -> None:
        with self._lock:
            self.check()
            if self.requests >= self.max_requests:
                raise PlannerError("TASK_BUDGET_EXCEEDED", "Task model request budget exhausted", {"budget": self.snapshot()})
            self.requests += 1

    def record_usage(self, usage: Any) -> None:
        if hasattr(usage, "model_dump"):
            usage = usage.model_dump()
        if not isinstance(usage, dict):
            return
        with self._lock:
            prompt = int(usage.get("prompt_tokens", usage.get("input_tokens", 0)) or 0)
            completion = int(usage.get("completion_tokens", usage.get("output_tokens", 0)) or 0)
            total = int(usage.get("total_tokens", prompt + completion) or 0)
            self.prompt_tokens += max(prompt, total - completion)
            self.completion_tokens += completion

    def record_action(self) -> None:
        with self._lock:
            self.check()
            if self.actions >= self.max_actions:
                raise PlannerError("TASK_BUDGET_EXCEEDED", "Task action budget exhausted", {"budget": self.snapshot()})
            self.actions += 1

    def record_replan(self) -> None:
        with self._lock:
            self.check()
            if self.replans >= self.max_replans:
                raise PlannerError("TASK_BUDGET_EXCEEDED", "Task recovery budget exhausted", {"budget": self.snapshot()})
            self.replans += 1

    def snapshot(self) -> dict[str, Any]:
        with self._lock:
            return {"requests": self.requests, "prompt_tokens": self.prompt_tokens,
                    "completion_tokens": self.completion_tokens,
                    "total_tokens": self.prompt_tokens + self.completion_tokens,
                    "actions": self.actions, "replans": self.replans,
                    "elapsed_s": self._clock() - self._started,
                    "remaining_s": self.remaining_s, "cancelled": bool(self.cancel_reason),
                    "limits": {"max_requests": self.max_requests, "max_tokens": self.max_tokens,
                               "max_actions": self.max_actions, "max_replans": self.max_replans,
                               "timeout_s": self.timeout_s}}


_current: ContextVar[TaskBudget | None] = ContextVar("embodied_task_budget", default=None)


def current_budget() -> TaskBudget | None:
    return _current.get()


@contextmanager
def budget_context(budget: TaskBudget):
    token = _current.set(budget)
    try:
        yield budget
    finally:
        _current.reset(token)

src/embodied_agent/models/contracts.py:
"""Transport-independent model response and planning error contracts."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Protocol

class PlannerError(RuntimeError):
    def __init__(self, code: str, message: str, details: dict[str, Any] | None = None):
        super().__init__(message)
        self.code = code
        self.details = details or {}


@dataclass(frozen=True)
class PlannerResponse:
    content: str
    planner_kind: str
    requested_model: str | None
    response_model: str | None
    usage: dict[str, Any] | None
    latency_s: float
    finish_reason: str | None
    request_id: str | None


class Planner(Protocol):
    kind: str

    def plan(self, instruction: str, snapshot: dict[str, Any], world: Any, *,
             feedback: Any = None, task_context: dict[str, Any] | None = None) -> PlannerResponse: ...

